// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {BaseHook} from "v4-periphery/src/utils/BaseHook.sol";
import {IPoolManager} from "v4-core/interfaces/IPoolManager.sol";
import {Hooks} from "v4-core/libraries/Hooks.sol";
import {PoolKey} from "v4-core/types/PoolKey.sol";
import {BalanceDelta} from "v4-core/types/BalanceDelta.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract PointsHook is BaseHook, ERC20 {
    mapping(address => uint256) public userPoints;
    uint256 public totalPoints;

    constructor(
        IPoolManager _poolManager,
        string memory name,
        string memory symbol
    ) BaseHook(_poolManager) ERC20(name, symbol) {}

    function getHookPermissions()
        public
        pure
        override
        returns (Hooks.Permissions memory)
    {
        return
            Hooks.Permissions({
                beforeInitialize: false,
                afterInitialize: false,
                beforeAddLiquidity: false,
                afterAddLiquidity: true,
                beforeRemoveLiquidity: false,
                afterRemoveLiquidity: false,
                beforeSwap: false,
                afterSwap: true,
                beforeDonate: false,
                afterDonate: false,
                beforeSwapReturnDelta: false,
                afterSwapReturnDelta: false,
                afterAddLiquidityReturnDelta: false,
                afterRemoveLiquidityReturnDelta: false
            });
    }

    // Changed from `afterAddLiquidity` to `_afterAddLiquidity` and updated return type
    function _afterAddLiquidity(
        address sender,
        PoolKey calldata key,
        IPoolManager.ModifyLiquidityParams calldata params,
        BalanceDelta delta,
        BalanceDelta hookFeesAccrued,
        bytes calldata data
    ) internal override returns (bytes4, BalanceDelta) {
        // Award points for adding liquidity
        uint256 points = 10; // Simple example: 10 points per liquidity add
        userPoints[sender] += points;
        totalPoints += points;

        // Mint tokens to reward the user
        _mint(sender, points);

        // Return the selector and a zero delta
        return (BaseHook.afterAddLiquidity.selector, BalanceDelta.wrap(0));
    }

    // Changed from `afterSwap` to `_afterSwap` and updated return type
    function _afterSwap(
        address sender,
        PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata hookData
    ) internal override returns (bytes4, int128) {
        // Award points for trading
        uint256 points = 5; // Simple example: 5 points per swap
        userPoints[sender] += points;
        totalPoints += points;

        // Mint tokens to reward the user
        _mint(sender, points);

        // Return the selector and a zero delta
        return (BaseHook.afterSwap.selector, 0);
    }
}

